import{_ as a,a0 as s,w as o,s as r,I as n,x as l,a1 as i,A as p,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse(`{"title":"輕鬆使用“Explain Shell”腳本來理解 Shell 命令 | LCTT x X-CMD","titleTemplate":false,"description":"輕鬆使用“Explain Shell”腳本來理解 Shell 命令 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"輕鬆使用“Explain Shell”腳本來理解 Shell 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"輕鬆使用“Explain Shell”腳本來理解 Shell 命令 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux","title":"輕鬆使用“Explain Shell”腳本來理解 Shell 命令","tag":"201508","desc":""},"relativePath":"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux.md","filePath":"[post].md"}`),h={name:"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux.md"};function d(u,e,x,g,w,c){const t=s("Link");return o(),r("div",null,[e[16]||(e[16]=n("h1",{id:"輕鬆使用-explain-shell-腳本來理解-shell-命令",tabindex:"-1"},[l("輕鬆使用“Explain Shell”腳本來理解 Shell 命令 "),n("a",{class:"header-anchor",href:"#輕鬆使用-explain-shell-腳本來理解-shell-命令","aria-label":"Permalink to “輕鬆使用“Explain Shell”腳本來理解 Shell 命令”"},"​")],-1)),e[17]||(e[17]=n("p",null,"我們在Linux上工作時，每個人都會遇到需要查找shell命令的幫助信息的時候。 儘管內置的幫助像man pages、whatis命令有所助益， 但man pages的輸出非常冗長， 除非是個有linux經驗的人，不然從大量的man pages中獲取幫助信息是非常困難的，而whatis命令的輸出很少超過一行， 這對初學者來説是不夠的。",-1)),e[18]||(e[18]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/07/Explain-Shell-Commands-in-Linux-Shell.jpeg",alt:"Explain Shell Commands in Linux Shell"})],-1)),e[19]||(e[19]=n("p",null,[n("em",null,"在Linux Shell中解釋Shell命令")],-1)),n("p",null,[e[1]||(e[1]=l("有一些第三方應用程序， 像我們在",-1)),i(t,{href:"http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/"},{default:p(()=>[...e[0]||(e[0]=[l("Linux 用户的命令列速查表",-1)])]),_:1}),e[2]||(e[2]=l("提及過的'cheat'命令。cheat是個優秀的應用程序，即使計算機沒有聯網也能提供shell命令的幫助， 但是它僅限於預先定義好的命令。",-1))]),e[20]||(e[20]=m(`<p>Jackson寫了一小段代碼，它能非常有效地在bash shell裏面解釋shell命令，可能最美之處就是你不需要安裝第三方包了。他把包含這段代碼的的文件命名為“explain.sh”。</p><h4 id="explain-sh工具的特性" tabindex="-1">explain.sh工具的特性 <a class="header-anchor" href="#explain-sh工具的特性" aria-label="Permalink to “explain.sh工具的特性”">​</a></h4><ul><li>易嵌入代碼。</li><li>不需要安裝第三方工具。</li><li>在解釋過程中輸出恰到好處的信息。</li><li>需要網絡連接才能工作。</li><li>純命令列工具。</li><li>可以解釋bash shell裏面的大部分shell命令。</li><li>無需使用root賬户。</li></ul><p><strong>先決條件</strong></p><p>唯一的條件就是&#39;curl&#39;包了。 在如今大多數Linux發行版裏面已經預安裝了curl包， 如果沒有你可以按照下面的命令來安裝。</p><pre><code># apt-get install curl 	[On Debian systems]
# yum install curl 		[On CentOS systems]
</code></pre><h3 id="在linux上安裝explain-sh工具" tabindex="-1">在Linux上安裝explain.sh工具 <a class="header-anchor" href="#在linux上安裝explain-sh工具" aria-label="Permalink to “在Linux上安裝explain.sh工具”">​</a></h3><p>我們要將下面這段代碼插入&#39;~/.bashrc&#39;文件（LCTT譯註: 若沒有該文件可以自己新建一個）中。我們要為每個用户以及對應的&#39;.bashrc&#39;文件插入這段代碼，但是建議你不要加在root用户下。</p><p>我們注意到.bashrc文件的第一行代碼以（#）開始， 這個是可選的並且只是為了區分餘下的代碼。</p><p># explain.sh 標記代碼的開始， 我們將代碼插入.bashrc文件的底部。</p><pre><code># explain.sh begins
explain () {
  if [ &quot;$#&quot; -eq 0 ]; then
    while read  -p &quot;Command: &quot; cmd; do
      curl -Gs &quot;https://www.mankier.com/api/explain/?cols=&quot;$(tput cols) --data-urlencode &quot;q=$cmd&quot;
    done
    echo &quot;Bye!&quot;
  elif [ &quot;$#&quot; -eq 1 ]; then
    curl -Gs &quot;https://www.mankier.com/api/explain/?cols=&quot;$(tput cols) --data-urlencode &quot;q=$1&quot;
  else
    echo &quot;Usage&quot;
    echo &quot;explain                  interactive mode.&quot;
    echo &quot;explain &#39;cmd -o | ...&#39;   one quoted command to explain it.&quot;
  fi
}
</code></pre><h3 id="explain-sh工具的使用" tabindex="-1">explain.sh工具的使用 <a class="header-anchor" href="#explain-sh工具的使用" aria-label="Permalink to “explain.sh工具的使用”">​</a></h3><p>在插入代碼並保存之後，你必須退出當前的會話然後重新登錄來使改變生效（LCTT譯註：你也可以直接使用命令<code>source~/.bashrc</code> 來讓改變生效）。每件事情都是交由‘curl’命令處理， 它負責將需要解釋的命令以及命令選項傳送給mankier服務，然後將必要的信息打印到Linux命令列。不必説的就是使用這個工具你總是需要連接網絡。</p><p>讓我們用explain.sh腳本測試幾個筆者不懂的命令例子。</p><p><strong>1.我忘了‘du -h’是幹嘛用的， 我只需要這樣做:</strong></p><pre><code>$ explain &#39;du -h&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Get-Help-on-du-Command.png" alt="Get Help on du Command"></p><p><em>獲得du命令的幫助</em></p><p><strong>2.如果你忘了&#39;tar -zxvf&#39;的作用，你可以簡單地如此做:</strong></p><pre><code>$ explain &#39;tar -zxvf&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Tar-Command-Help.png" alt="Tar Command Help"></p><p><em>Tar命令幫助</em></p><p><strong>3.我的一個朋友經常對&#39;whatis&#39;以及&#39;whereis&#39;命令的使用感到困惑，所以我建議他：</strong></p><p>在終端簡單的地敲下explain命令進入交互模式。</p><pre><code>$ explain
</code></pre><p>然後一個接着一個地輸入命令，就能在一個窗口看到他們各自的作用：</p><pre><code>Command: whatis
Command: whereis
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Whatis-Whereis-Commands-Help.png" alt="Whatis Whereis Commands Help"></p><p><em>Whatis/Whereis命令的幫助</em></p><p>你只需要使用“Ctrl+c”就能退出交互模式。</p><p><strong>4. 你可以通過管道來請求解釋更多的命令。</strong></p><pre><code>$ explain &#39;ls -l | grep -i Desktop&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Get-Help-on-Multiple-Commands.png" alt="Get Help on Multiple Commands"></p><p><em>獲取多條命令的幫助</em></p><p>同樣地，你可以請求你的shell來解釋任何shell命令。 前提是你需要一個可用的網絡。輸出的信息是基於需要解釋的命令，從服務器中生成的，因此輸出的結果是不可定製的。</p><p>對於我來説這個工具真的很有用，並且它已經榮幸地添加在我的.bashrc文件中。你對這個項目有什麼想法？它對你有用麼？它的解釋令你滿意嗎？請讓我知道吧！</p><p>請在下面評論為我們提供寶貴意見，喜歡並分享我們以及幫助我們得到傳播。</p><hr>`,38)),n("p",null,[e[4]||(e[4]=l("via: ",-1)),i(t,{href:"http://www.tecmint.com/explain-shell-commands-in-the-linux-shell/"},{default:p(()=>[...e[3]||(e[3]=[l("http://www.tecmint.com/explain-shell-commands-in-the-linux-shell/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=l("作者：",-1)),i(t,{href:"http://www.tecmint.com/author/avishek/"},{default:p(()=>[...e[5]||(e[5]=[l("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=l(" 譯者：",-1)),i(t,{href:"https://github.com/dingdongnigetou"},{default:p(()=>[...e[6]||(e[6]=[l("dingdongnigetou",-1)])]),_:1}),e[10]||(e[10]=l(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[l("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=l("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[l("LCTT",-1)])]),_:1}),e[14]||(e[14]=l(" 原創翻譯，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[l("Linux中國",-1)])]),_:1}),e[15]||(e[15]=l(" 榮譽推出",-1))])])}const T=a(h,[["render",d]]);export{f as __pageData,T as default};
